 Input input(int revision,String status){return new Input("Analista SQL","Previsão sintética, sem vaga aberta","Tecnologia",3,"Ensino médio","Inicial","Brasil","Remoto",LocalDate.now().toString(),LocalDate.now().plusMonths(6).toString(),status,revision);}
 long job(JdbcTemplate jdbc,long company,String publication,String payment){return jdbc.queryForObject("INSERT INTO company_listings(company_id,kind,title,area,description,requirements,location,modality,url,contact_email,publication_status,is_internship,payment_status) VALUES (?,'job','Synthetic SQL job','Tecnologia','Fixture','SQL','Brasil','Remoto','https://example.test','private-contact@future.test',?,TRUE,?) RETURNING id",Long.class,company,publication,payment);}
 JsonNode ok(String method,String path,Object body,String token)throws Exception{var response=send(method,path,body,token);assertEquals(200,response.statusCode(),response.body());return json.readTree(response.body());}
 HttpResponse<String> send(String method,String path,Object body,String token)throws Exception{var request=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(30)).header("Content-Type","application/json");if(token!=null)request.header("Authorization","Bearer "+token);return client.send(request.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
